css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; }
.loader i { position: absolute; bottom: 4%; width: 5%; border-radius: 3px; background: var(--accent); transform-origin: 50% 100%; transform: scaleY(0); animation: scaf-post calc(var(--loader-speed) * 3.2) ease-out infinite; }
.loader i:nth-of-type(1) { left: 8%; height: 92%; }
.loader i:nth-of-type(2) { left: 47%; height: 92%; animation-delay: calc(var(--loader-speed) * .12); }
.loader i:nth-of-type(3) { right: 8%; height: 92%; animation-delay: calc(var(--loader-speed) * .24); }
.loader span { position: absolute; left: 6%; right: 6%; height: 7%; border-radius: 3px; background: linear-gradient(var(--accent-2), color-mix(in srgb, #000 22%, var(--accent-2))); transform-origin: 0 50%; transform: scaleX(0); animation: scaf-plank calc(var(--loader-speed) * 3.2) cubic-bezier(.4, 0, .4, 1) infinite; }
.loader span:nth-of-type(1) { bottom: 8%; animation-delay: calc(var(--loader-speed) * .4); }
.loader span:nth-of-type(2) { bottom: 32%; animation-delay: calc(var(--loader-speed) * .64); }
.loader span:nth-of-type(3) { bottom: 56%; animation-delay: calc(var(--loader-speed) * .88); }
.loader span:nth-of-type(4) { bottom: 80%; animation-delay: calc(var(--loader-speed) * 1.12); }
@keyframes scaf-post { 0%, 3% { transform: scaleY(0); opacity: 0; } 18%, 76% { transform: scaleY(1); opacity: 1; } 92%, 100% { transform: scaleY(0); opacity: 0; } }
@keyframes scaf-plank { 0%, 3% { transform: scaleX(0); opacity: 0; } 16%, 74% { transform: scaleX(1); opacity: 1; } 90%, 100% { transform: scaleX(0); opacity: 0; } }
